oxy_webhelp_navlinks = {"saphana_setup_system-d39307e40821":{"topics":[{"title":"SAP HANA deployment options","shortdesc":"<p class=\"shortdesc\">SAP HANA supports two deployment options: scale-up and scale-out. The differences         between these options affect how you configure data protection with <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/saphana_evaluate_deployment_options.html","attributes":{"data-id":"saphana_evaluate_deployment_options"},"menu":{"hasChildren":false},"tocID":"saphana_evaluate_deployment_options-d39307e40835","next":"saphana_evaluate_deployment_options-d39307e40835"},{"title":"Rubrik Backup Service for SAP HANA","shortdesc":"<p class=\"shortdesc\">Install and configure the Rubrik Backup Service on a SAP HANA host to allow backup and     restore of SAP HANA databases.<\/p>","href":"rbs\/rbs_sap_hana.html","attributes":{"data-id":"rbs_sap_hana"},"menu":{"hasChildren":false},"tocID":"rbs_sap_hana-d39307e40877","next":"rbs_sap_hana-d39307e40877"},{"title":"Adding an SAP HANA host","shortdesc":"<p class=\"shortdesc\">To begin managing and protecting SAP HANA databases on a Linux host, add the host to         the Rubrik cluster.<\/p>","href":"saas\/adding_a_host.html","attributes":{"data-id":"adding_a_host"},"menu":{"hasChildren":false},"tocID":"adding_a_host-d39307e40899","next":"adding_a_host-d39307e40899"},{"title":"Adding an SAP HANA system","shortdesc":"<p class=\"shortdesc\">Add an SAP HANA system to the <span class=\"ph\">RSC<\/span> domain to start protecting SAP HANA         workloads.<\/p>","href":"saas\/adding_a_sap_hana_system.html","attributes":{"data-id":"adding_a_sap_hana_system"},"menu":{"hasChildren":false},"tocID":"adding_a_sap_hana_system-d39307e40938","next":"adding_a_sap_hana_system-d39307e40938"}]}};